private static string ApplyStep(string target, RuleStep step, int sequenceIndex)
{
    return step switch
    {
        ReplaceStep rs => ApplyReplace(target, rs),
        InsertStep ins => ApplyInsert(target, ins),
        RemoveStep rem => ApplyRemove(target, rem),
        SequenceStep seq => ApplySequence(target, seq, sequenceIndex),
        CaseStep cs => ApplyCase(target, cs),
        _ => target,
    };
}

private static string ApplyReplace(string target, ReplaceStep step)
{
    if (step.Regex)
    {
        var options = step.IgnoreCase ? RegexOptions.IgnoreCase : RegexOptions.None;
        var regex = new Regex(step.Find, options, TimeSpan.FromSeconds(1));
        return regex.Replace(target, step.ReplaceWith);
    }

    if (step.Find.Length == 0)
    {
        return target;
    }

    var comparison = step.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
    return target.Replace(step.Find, step.ReplaceWith, comparison);
}

private static string ApplyInsert(string target, InsertStep step)
{
    switch (step.Position)
    {
        case InsertPosition.Prefix:
            return step.Text + target;
        case InsertPosition.Suffix:
            return target + step.Text;
        case InsertPosition.Index:
            int clamped = Math.Clamp(step.Index, 0, target.Length);
            return target[..clamped] + step.Text + target[clamped..];
        default:
            return target;
    }
}

