if (_currentPlan == null || _currentDir == null) return;

List<FileEntry> freshFiles;
try
{
    freshFiles = FileScanner.Scan(_currentDir);
}
catch (Exception ex)
{
    _folderError = $"無法讀取資料夾：{ex.Message}";
    UpdateStatusStrip();
    return;
}

RenamePlan freshPlan;
try
{
    freshPlan = PlanBuilder.Build(freshFiles, _rules);
}
catch (Exception ex)
{
    _ruleError = $"規則有誤：{ex.Message}";
    UpdateStatusStrip();
    return;
}

if (!PlansEqual(freshPlan, _currentPlan))
{
    _files = freshFiles;
    _currentPlan = freshPlan;
    _ruleError = null;
    _folderError = null;
    RefreshPreviewGrid();
    _statusLabel.ForeColor = Color.Firebrick;
    _statusLabel.Text = "資料夾內容已變更，預覽已更新，請再按一次套用。";
    UpdateButtonStates();
    return;
}

var summary = _currentPlan.Summary;
string confirmMsg =
    $"即將重新命名 {summary.Ok} 個檔案。\n" +
    $"略過：碰撞 {summary.Collision}、不合法 {summary.Invalid}、未變更 {summary.Unchanged}。\n" +
    "此操作可用「復原上一次」還原。";
var confirm = MessageBox.Show(this, confirmMsg, "確認套用", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);
if (confirm != DialogResult.Yes) return;

var moves = _currentPlan.Items
    .Where(i => i.Status == ItemStatus.Ok)
    .Select(i => new RenameMove { From = i.Original, To = i.Proposed })
    .ToList();

string dir = _currentDir;
SetBusy(true);
var progress = new Progress<int>(p => _progressBar.Value = Math.Clamp(p, 0, 100));

RenameOutcome outcome;
try
{
    outcome = await Task.Run(() => RenameExecutor.Apply(dir, moves, AppPaths.JournalDirectory, progress));
}
catch (Exception ex)
{
    SetBusy(false);
    MessageBox.Show(this, ex.Message, "套用失敗", MessageBoxButtons.OK, MessageBoxIcon.Error);
    return;
}

SetBusy(false);

